import java.util.*;

class WordDistance {
  private final Map<String, List<Integer>> positions = new HashMap<>();

  public WordDistance(String[] wordsDict) {
    for (int i = 0; i < wordsDict.length; i++) positions.computeIfAbsent(wordsDict[i], k -> new ArrayList<>()).add(i);
  }

  public int shortest(String word1, String word2) {
    List<Integer> a = positions.get(word1), b = positions.get(word2);
    int best = Integer.MAX_VALUE;
    // both lists are sorted: advance whichever index is smaller
    for (int i = 0, j = 0; i < a.size() && j < b.size(); ) {
      best = Math.min(best, Math.abs(a.get(i) - b.get(j)));
      if (a.get(i) < b.get(j)) i++;
      else j++;
    }
    return best;
  }
}
